function duotoneProcess(data,w,h,opts){
  opts=opts||{};
  var sh=opts.shadow||[0,0,0], hi=opts.highlight||[255,255,255];
  var out=new Uint8ClampedArray(data.length);
  for(var i=0;i<data.length;i+=4){
    var lum=(0.299*data[i]+0.587*data[i+1]+0.114*data[i+2])/255;
    out[i]=sh[0]+(hi[0]-sh[0])*lum;
    out[i+1]=sh[1]+(hi[1]-sh[1])*lum;
    out[i+2]=sh[2]+(hi[2]-sh[2])*lum;
    out[i+3]=data[i+3];
  }
  return out;
}

var EXPORTS={duotoneProcess:duotoneProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.DuotoneForgePure = EXPORTS; }
